class Solution { public: int sumOfFlooredPairs(vector<int>& nums){int maximum=*max_element(nums.begin(),nums.end());vector<int> frequency(maximum+1),prefix(maximum+1);for(int value:nums)++frequency[value];for(int value=1;value<=maximum;++value)prefix[value]=prefix[value-1]+frequency[value];long long answer=0;for(int divisor=1;divisor<=maximum;++divisor)if(frequency[divisor])for(int start=divisor;start<=maximum;start+=divisor){int count=prefix[min(maximum,start+divisor-1)]-prefix[start-1];answer=(answer+1LL*frequency[divisor]*(start/divisor)*count)%1000000007;}return answer;} };
